def clone_repo(url: str, dest_dir: Path) -> bool:
    """Perform shallow clone of remote repository."""
    try:
        cmd = ["git", "clone", "--depth", "1", url, str(dest_dir)]
        proc = subprocess.run(cmd, capture_output=True, text=True, check=False)
        return proc.returncode == 0
    except (OSError, subprocess.SubprocessError) as exc:
        err_console.print(f"[red]error:[/red] failed to execute git clone: {exc}")
        return False

def detect_languages_and_type(root: Path) -> dict[str, Any]:
    """Detect project languages, manifests, and classification."""
    languages: list[str] = []
    manifests: list[str] = []
    is_cli = False

    if (root / "pyproject.toml").is_file() or (root / "setup.py").is_file():
        languages.append("python")
        manifests.append("pyproject.toml" if (root / "pyproject.toml").is_file() else "setup.py")
        if (root / "pyproject.toml").is_file():
            content = (root / "pyproject.toml").read_text(encoding="utf-8", errors="replace")
            if "project.scripts" in content or "tool.poetry.scripts" in content:
                is_cli = True

    if (root / "package.json").is_file():
        languages.append("javascript/typescript")
        manifests.append("package.json")
        try:
            pkg_data = json.loads((root / "package.json").read_text(encoding="utf-8", errors="replace"))
            if "bin" in pkg_data:
                is_cli = True
        except (json.JSONDecodeError, OSError):
            pass

    if (root / "Cargo.toml").is_file():
        languages.append("rust")
        manifests.append("Cargo.toml")
        content = (root / "Cargo.toml").read_text(encoding="utf-8", errors="replace")
        if "[[bin]]" in content or "clap" in content:
            is_cli = True

    if (root / "go.mod").is_file():
        languages.append("go")
        manifests.append("go.mod")

    # Check common CLI entry files
    for candidate in ("cli.py", "main.py", "index.ts", "main.go", "src/main.rs"):
        if (root / candidate).is_file():
            try:
                txt = (root / candidate).read_text(encoding="utf-8", errors="replace")
                if any(k in txt for k in ("argparse", "click", "typer", "commander", "yargs", "cobra")):
                    is_cli = True
            except OSError:
                pass

    project_type = "CLI Tool" if is_cli else ("Library / Package" if manifests else "General Codebase")

    return {
        "languages": languages or ["unknown"],
        "manifests": manifests,
        "is_cli": is_cli,
        "project_type": project_type,
    }

def extract_readme_summary(root: Path) -> dict[str, Any]:
    """Extract summary, installation instructions, and code blocks from README."""
    readme_path = None
    for name in ("README.md", "README.rst", "README.txt", "readme.md"):
        cand = root / name
        if cand.is_file():
            readme_path = cand
            break

    if not readme_path:
        return {"has_readme": False, "title": root.name, "description": "", "commands": []}

    try:
        content = readme_path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {"has_readme": False, "title": root.name, "description": "", "commands": []}


    # Extract title
    title_match = re.search(r"^#\s+(.+)$", content, re.MULTILINE)
    title = title_match.group(1).strip() if title_match else root.name

    # Extract first non-header paragraph
    paragraphs = [p.strip() for p in content.split("\n\n") if p.strip() and not p.strip().startswith("#")]
    description = paragraphs[0] if paragraphs else ""

    # Extract command snippets from bash/shell blocks
    code_blocks = re.findall(r"```(?:bash|shell|sh|console)?\s*\n(.*?)\n```", content, re.DOTALL)
    commands: list[str] = []
    for block in code_blocks:
        for line in block.splitlines():
            line = line.strip().lstrip("$").strip()
            if line and not line.startswith("#") and len(line) < 120:
                commands.append(line)
                if len(commands) >= 5:
                    break
        if len(commands) >= 5:
            break

    return {
        "has_readme": True,
        "title": title,
        "description": description[:300],
        "commands": commands,
    }

def is_git_url(target: str) -> bool:
    """Check if target string looks like a git remote repository URL."""
    return target.startswith(("https://", "http://", "git@")) or target.endswith(".git")

def decide(payload):
    command = extract_command(payload)
    if command is None:
        # Not a shell/terminal-command-shaped tool call — nothing to check,
        # so fail open rather than scanning unrelated payloads (file content,
        # etc.) against command deny-patterns.
        return {"decision": "allow"}

    for pattern, reason, confirmable in DENY_RULES:
        if pattern.search(command):
            if confirmable and CONFIRMED_MARKER in command:
                continue
            return {"decision": "deny", "reason": reason}

    return {"decision": "allow"}

def main():
    try:
        raw = sys.stdin.read()
        payload = json.loads(raw)
        result = decide(payload)
    except Exception:  # noqa: BLE001 - must never block tool use on this hook's own bugs
        # Never block tool use because this hook itself is broken or the
        # input was malformed/non-JSON.
        result = {"decision": "allow"}

    print(json.dumps(result))

def ensure_docs_dir(root: Path) -> Path:
    """Ensure `.buddhi/docs/` exists under root; return it."""
    docs_dir = root / BUDDHI_DIR_NAME / DOCS_DIR_NAME
    try:
        docs_dir.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        raise BuddhiFsError(f"could not prepare {docs_dir}: {exc}") from exc
    return docs_dir

def migrate_legacy_workflows(agents_dir: Path) -> WorkflowMigrationReport:
    """Migrate legacy Antigravity workflows (.agents/workflows/*.md) to skills (.agents/skills/<name>/SKILL.md)
    and remove legacy workflow files and directory to prevent conflicts.

    Follows the Antigravity migration standard:
    1. For each .agents/workflows/<name>.md:
       - If .agents/skills/<name>/SKILL.md exists, preserve existing without overwrite.
       - If .agents/skills/<name>/SKILL.md does not exist, convert workflow to SKILL.md
         ensuring valid YAML frontmatter (name and description).
       - Delete the legacy workflow file.
    2. Clean up or remove .agents/workflows.json manifest if present.
    3. Remove the .agents/workflows directory once all workflows are cleaned up.
    """
    report = WorkflowMigrationReport()
    workflows_dir = agents_dir / "workflows"
    if not workflows_dir.is_dir():
        return report

    # 1. Convert active workflow files (.md)
    for wf_file in sorted(workflows_dir.glob("*.md")):
        if wf_file.name.endswith(".bak"):
            continue
        skill_name = "spec-plan" if wf_file.stem == "plan" else wf_file.stem
        target_skill_dir = agents_dir / "skills" / skill_name
        target_skill_file = target_skill_dir / "SKILL.md"

        if target_skill_file.exists():
            report.skipped_existing.append(target_skill_file)
        else:
            try:
                target_skill_dir.mkdir(parents=True, exist_ok=True)
                raw_content = wf_file.read_text(encoding="utf-8")
                converted_content = _ensure_skill_frontmatter(raw_content, default_name=skill_name)
                target_skill_file.write_text(converted_content, encoding="utf-8")
                report.migrated.append(target_skill_file)
            except OSError as exc:
                raise BuddhiFsError(f"could not convert workflow to skill {target_skill_file}: {exc}") from exc

    # 2. Remove all legacy workflow files (.md and .md.bak)
    removed_names: set[str] = set()
