function tiers() {
  const core = read('antislop.md')
  const part2 = core.split('## Part 2:')[1]?.split('## Part 3:')[0] ?? ''

  const group = {}
  let current = null
  for (const line of part2.split('\n')) {
    const g = line.match(/^### Group \d: ([^(]+)/)
    if (g) current = g[1].trim()
    const r = line.match(/^#### (R-\d{2}) —/)
    if (r && current) group[r[1]] = current
  }

  const block = {}
  let currentBlock = null
  for (const line of (core.split('## Delivery Gate (Mandatory)')[1] ?? '').split('\n')) {
    const b = line.match(/^### (Block \d):/)
    if (b) currentBlock = b[1]
    for (const m of line.matchAll(/\((R-\d{2})\)/g)) {
      if (!block[m[1]]) block[m[1]] = currentBlock
    }
  }

  const wants = { 'Hard Gate': 'Block 1', 'Purpose-Gate': 'Block 2', 'Quality Locks': 'Block 4' }
  const bad = []
  for (const [rule, grp] of Object.entries(group).sort()) {
    const want = wants[grp]
    const got = block[rule]
    if (want && got && want !== got) bad.push(`${rule} is a ${grp} rule but the gate cites it from ${got}`)
  }
  return bad
}

function versions() {
  // A malformed file is already reported by the manifest check; do not crash here.
  const json = (p) => {
    try {
      return JSON.parse(read(p))
    } catch {
      return null
    }
  }
  const want = json('cli/package.json')?.version
  if (!want) return ['cli/package.json has no readable version']

  const found = [
    // The lock file carries the version twice, and npm ci will not correct a stale one.
    ['cli/package-lock.json', json('cli/package-lock.json')?.version],
    ['cli/package-lock.json (packages "")', json('cli/package-lock.json')?.packages?.['']?.version],
    // The Cline plugin manifest and, from v3.2.17, the Pi package. Same release.
    ['package.json', json('package.json')?.version],
    ['.claude-plugin/plugin.json', json('.claude-plugin/plugin.json')?.version],
    ['.claude-plugin/marketplace.json', json('.claude-plugin/marketplace.json')?.plugins?.[0]?.version],
    ['.codex-plugin/plugin.json', json('.codex-plugin/plugin.json')?.version],
    ['.cursor-plugin/plugin.json', json('.cursor-plugin/plugin.json')?.version],
    ['.omp-plugin/marketplace.json', json('.omp-plugin/marketplace.json')?.plugins?.[0]?.version],
    ['.kimi-plugin/plugin.json', json('.kimi-plugin/plugin.json')?.version],
    // Stamped into every install, so a stale one makes the installer misreport what is on disk.
    ['skills/antislop/VERSION', read('skills/antislop/VERSION').trim()],
    ['cli/lib/banner.mjs', read('cli/lib/banner.mjs').match(/installer v(\d+\.\d+\.\d+)/)?.[1]],
    ['skills/antislop-human/contrast-mcp.py', read('skills/antislop-human/contrast-mcp.py').match(/SERVER_VERSION = "(\d+\.\d+\.\d+)"/)?.[1]],
    // The contributors image is cached per URL, so a changed version is what makes it redraw.
    ['README.md (contributors image)', read('README.md').match(/contrib\.rocks\/image\?repo=[^"'&\s]+&v=(\d+\.\d+\.\d+)/)?.[1]],
  ]

  return found
    .filter(([, got]) => got !== want)
    .map(([file, got]) => `${file} says ${got ?? 'nothing'}, cli/package.json says ${want}`)
}

function buildIndex() {
  const names = fs
    .readdirSync(path.join(root, 'skills'), { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)

  const unlisted = names.filter((n) => !NOTES[n])
  if (unlisted.length) throw new Error(`scripts/skill-index.mjs has no intro for: ${unlisted.join(', ')}`)
  const gone = Object.keys(NOTES).filter((n) => !names.includes(n))
  if (gone.length) throw new Error(`scripts/skill-index.mjs describes a skill that is gone: ${gone.join(', ')}`)

  const out = []
  for (const name of Object.keys(NOTES)) {
    const raw = fs.readFileSync(path.join(root, 'skills', name, 'SKILL.md'), 'utf8').replace(/\r\n/g, '\n')
    const rows = []
    for (const section of blocksOf(unfenced(raw), '##')) {
      const title = section.split('\n')[0].trim()
      const found = blocksOf(section, '###')
        .filter((block) => ENTRY.test(block))
        .map((block) => block.split('\n')[0].trim())
      if (found.length) rows.push(`| ${title} | ${found.join(', ')} |`)
    }
    out.push(`### ${name}`, '', NOTES[name], '')
    if (rows.length) out.push(HEAD, ...rows, '')
  }
  return out.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n'
}

def linearize(channel):
    c = channel / 255.0
    if c <= 0.03928:
        return c / 12.92
    return ((c + 0.055) / 1.055) ** 2.4

def luminance(rgb):
    r, g, b = (linearize(ch) for ch in rgb)
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast_ratio(color_a, color_b):
    lum_a, lum_b = luminance(color_a), luminance(color_b)
    lighter, darker = sorted((lum_a, lum_b), reverse=True)
    return (lighter + 0.05) / (darker + 0.05)

def parse_hex(value):
    value = value.strip().lstrip("#")
    if len(value) == 3:
        value = "".join(ch * 2 for ch in value)
    if not re.fullmatch(r"[0-9A-Fa-f]{6}", value):
        raise ValueError(f"expected a hex color like #FFFFFF, got {value!r}")
    return tuple(int(value[i:i + 2], 16) for i in (0, 2, 4))

def parse_pairing(pairing):
    """Turn 'White on #333333' or '#555555 on black' into two RGB tuples."""
    colors = []
    for token in re.split(r"\s+on\s+", pairing):
        token = token.strip()
        match = re.search(r"#[0-9A-Fa-f]{3,6}", token)
        if match:
            colors.append(parse_hex(match.group(0)))
        elif token.lower() in NAMED_COLORS:
            colors.append(NAMED_COLORS[token.lower()])
        else:
            raise ValueError(f"cannot parse {token!r} from pairing {pairing!r}")
    if len(colors) != 2:
        raise ValueError(f"expected two colors in pairing {pairing!r}")
    return tuple(colors)

def parse_reference_rows(path):
    """Reference table rows from SKILL.md, with the ratio already a float.

    A row that does not split into four cells is dropped silently, not raised.
    """
    rows = []
    with open(path, encoding="utf-8") as handle:
        in_table = False
        for raw in handle:
            line = raw.rstrip("\n")
            if line.startswith(REFERENCE_HEADER):
                in_table = True
                continue
            if not in_table:
                continue
            if not line.startswith("|"):
                break
            if line.startswith("|---"):
                continue
            cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
            if len(cells) != 4:
                continue
            pairing, ratio, normal, large = cells
            rows.append({
                "pairing": pairing,
                "ratio": float(ratio),
                "normal": normal,
                "large": large,
            })
    return rows

def main(argv):
    if len(argv) == 1 and argv[0] == "--selftest":
        return selftest()
    if len(argv) != 2:
        print("usage: python3 contrast-check.py <hex1> <hex2> | --selftest")
        return 2
    try:
        ratio = contrast_ratio(parse_hex(argv[0]), parse_hex(argv[1]))
    except ValueError as exc:
        print(f"error: {exc}")
        return 2

    normal = ratio >= 4.5
    large = ratio >= 3.0
    print(f"ratio: {ratio:.2f}:1")
    print(f"normal text (4.5:1): {'PASS' if normal else 'FAIL'}")
    print(f"large text  (3.0:1): {'PASS' if large else 'FAIL'}")
    return 0 if normal and large else 1

def _send(msg):
    sys.stdout.write(json.dumps(msg) + "\n")
    sys.stdout.flush()

def relative_luminance(hex_color):
    h = hex_color.strip().lstrip("#")
    if len(h) == 3:
        h = "".join(ch * 2 for ch in h)
    r, g, b = (int(h[i : i + 2], 16) for i in (0, 2, 4))
    return 0.2126 * _channel(r) + 0.7152 * _channel(g) + 0.0722 * _channel(b)

def contrast_ratio(fg, bg):
    """The unrounded WCAG ratio. Callers decide what to print, never what to compare."""
    l1, l2 = relative_luminance(fg), relative_luminance(bg)
    lighter, darker = max(l1, l2), min(l1, l2)
    return (lighter + 0.05) / (darker + 0.05)

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            msg = json.loads(line)
        except json.JSONDecodeError:
            continue

        msg_id = msg.get("id")
        method = msg.get("method")

        if method == "initialize":
            _reply(msg_id, {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {"tools": {}},
                "serverInfo": {"name": SERVER_NAME, "version": SERVER_VERSION},
            })
        elif method == "notifications/initialized":
            pass
        elif method == "ping":
            _reply(msg_id, {})
        elif method == "tools/list":
            _reply(msg_id, {"tools": TOOLS})
        elif method == "tools/call":
            params = msg.get("params") or {}
            name = params.get("name")
            args = params.get("arguments") or {}
            if name == "check_contrast":
                try:
                    result = check_contrast(args["foreground"], args["background"])
                    _reply(msg_id, _text(json.dumps(result)))
                except Exception as exc:
                    _reply(msg_id, _error("check_contrast failed: " + str(exc)))
            else:
                _reply(msg_id, _error("Unknown tool: " + str(name)))
        elif msg_id is not None:
            _reply(msg_id, {})

function discover() {
  const found = new Map();
  for (const category of fs.readdirSync(SRC, { withFileTypes: true })) {
    if (!category.isDirectory()) continue;
    const categoryDir = path.join(SRC, category.name);
    for (const skill of fs.readdirSync(categoryDir, { withFileTypes: true })) {
      if (!skill.isDirectory()) continue;
      const dir = path.join(categoryDir, skill.name);
      if (!fs.existsSync(path.join(dir, 'SKILL.md'))) continue;
      const clash = found.get(skill.name);
      if (clash) {
        throw new Error(
          `two skills flatten to the same name: ${path.relative(REPO, clash.dir)} and ${path.relative(REPO, dir)}`,
        );
      }
      found.set(skill.name, { name: skill.name, category: category.name, dir });
    }
  }
  return [...found.values()].sort((a, b) => a.name.localeCompare(b.name));
}

function flattenLinks(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) flattenLinks(full);
    else if (entry.name.endsWith('.md')) {
      const before = fs.readFileSync(full, 'utf8');
      const after = before.replace(CROSS_CATEGORY_LINK, '](../');
      if (after !== before) fs.writeFileSync(full, after);
    }
  }
}

function linkTarget(linkPath) {
  try {
    return fs.readlinkSync(linkPath);
  } catch {
    return null;
  }
}

function planeMatrix(o, ex, ey) {
  const p0 = at(o);
  const px = at(G.add3(o, ex));
  const py = at(G.add3(o, ey));
  const v = (x) => x.toFixed(4);
  return `matrix(${v(px[0] - p0[0])} ${v(px[1] - p0[1])} ${v(py[0] - p0[0])} ${v(py[1] - p0[1])} ${p0[0].toFixed(2)} ${p0[1].toFixed(2)})`;
}

function put(name, ref, svg, shapes = [], { bias = 0, ...rest } = {}) {
  return R.put({ name, at: ref, bias, svg, shapes, piece: "cab", ...rest });
}

function ball(name, c, r, style = {}, { bias = 0, extra = "" } = {}) {
  const shape = record(A.ball(c, r, { name }));
  put(name, c, S(G.sphereOf(c, r, P, { steps: 32 }), { tone: "mid", ...style }) + extra, [shape], { bias });
  return shape;
}

function box(name, [x0, y0, z0], [x1, y1, z1], style = {}, { r = 0.4, steps = 2, bevel = 0, extra = "", inner = "", bias = 0 } = {}) {
  const plan = { x: x0, y: y0, w: x1 - x0, d: y1 - y0, r };
  const shape = record(A.slab(plan, z0, z1 - z0, { name }, steps));
  put(name, [(x0 + x1) / 2, (y0 + y1) / 2, (z0 + z1) / 2], S(k.slabOf(plan, z0, z1 - z0, P, steps, bevel), { tone: "mid", ...style, inner }) + extra, [shape], { bias });
  return shape;
}

function cable(name, points, r = 0.5, { tone = "mid", bend = 3, ends = [true, true], shells = [false, false], rings, maxLength = 16, bias = 0.05, limp = true, touch, bundle } = {}) {
  const route = G.fillet(points, Math.max(bend, r * 2.6), 10, { P, tube: r });
  const total = G.pathLength(route);
  const SHELL = Math.max(1.6, r * 2.4);
  const gaps = [...(shells[0] ? [[0, SHELL]] : []), ...(shells[1] ? [[total - SHELL, total]] : [])];
  R.route(name, route, r, { gaps, limp, touch, bundle, rims: shells.map((on) => (on ? r * 1.9 : r)), piece: "cab" });
  CABLES.push(name);
  tubePieces(route, r, P, { maxLength, spacing: Math.max(0.6, Math.min(1.6, r)), gaps, ...(rings ? { rings } : {}) }).forEach((piece, index) =>
    put(`${name}:${index}`, piece.mid, tubeSvg(piece, { tone }), [A.tube(piece.points, piece.radii)], { bias, route: name, chunk: index, attrs: ` data-route="${name}" data-chunk="${index}"` }),
  );
  [0, 1].forEach((index) => {
    const end = index ? route[route.length - 1] : route[0];
    if (shells[index]) {
      const tangent = G.tangentAlong(route, index ? total : 0);
      const F = G.frameAlong(end, tangent);
      const [s0, s1] = index ? [-SHELL, 0] : [0, SHELL];
      const shape = record(A.disc(F, s0, s1, r * 1.9, { name: `${name}.shell${index}`, owner: name }));
      put(`${name}.shell${index}`, G.add3(end, G.mul3(tangent, (s0 + s1) / 2)), S(G.disc(s0, s1, r * 1.9, F, P, { steps: 20, bevel: 0.2 }), { tone: "mid" }), [shape], { bias: bias + 0.1 });
    } else if (ends[index]) {
