  out.push(`<g class="nt-button" data-part="button">${S(k.cylinder(x, y, 6.6, 4.6, 3.4, P, 36, 0.5), { tone: "hi", crease: "lo" })}${L(k.ring(x, y, 4.2, 8, P, 32), { tone: "faint" })}</g>`);
