function checkBlip(s: number, gain = 1) {
  place(s, 0.22, (_, t) => {
    const f = t < 0.06 ? hz(84) : hz(88);
    return Math.sin(2 * Math.PI * f * t) * env(t < 0.06 ? t : t - 0.06, 0.002, 0.05) * 0.8;
  }, 0.3 * gain, 0.1, 0.4);
}

function ding(s: number, midi = 96, gain = 1) {
  place(s, 1.6, (_, t) => {
    const f = hz(midi);
    return (Math.sin(2 * Math.PI * f * t) + 0.4 * Math.sin(2 * Math.PI * f * 2.76 * t) * Math.exp(-t / 0.2) + 0.2 * Math.sin(2 * Math.PI * f * 5.4 * t) * Math.exp(-t / 0.08)) * env(t, 0.002, 0.45);
  }, 0.16 * gain, 0, 0.6);
}

function kick(s: number, gain = 1) {
  place(s, 0.45, (_, t) => {
    const f = 45 + 120 * Math.exp(-t / 0.03);
    const ph = 45 * t + (120 * 0.03) * (1 - Math.exp(-t / 0.03));
    const click = t < 0.004 ? noise() * (1 - t / 0.004) * 0.5 : 0;
    return (Math.sin(2 * Math.PI * ph) * env(t, 0.001, 0.16) + click) * (f > 0 ? 1 : 0);
  }, 0.95 * gain);
}

function ping(s: number, gain = 1) {
  place(s, 1.4, (_, t) => {
    const f = 1500 * Math.exp(-t / 0.4) + 700;
    return Math.sin(2 * Math.PI * f * t) * env(t, 0.001, 0.25);
  }, 0.22 * gain, 0, 0.9);
}

function pop(s: number, pitch = 1, gain = 1, pan = 0) {
  place(s, 0.09, (_, t) => {
    const f = (500 + 700 * Math.exp(-t / 0.012)) * pitch;
    return Math.sin(2 * Math.PI * f * t) * env(t, 0.001, 0.025);
  }, 0.32 * gain, pan, 0.25);
}

function reverb(inp: Float32Array, spread: number) {
  const out = new Float32Array(N);
  const combs = [1557, 1617, 1491, 1422].map((d) => ({ d: d + spread, buf: new Float32Array(d + spread), i: 0, lp: 0 }));
  for (let k = 0; k < N; k++) {
    let acc = 0;
    for (const c of combs) {
      const y = c.buf[c.i];
      c.lp = y * 0.6 + c.lp * 0.4;
      c.buf[c.i] = inp[k] + c.lp * 0.8;
      c.i = (c.i + 1) % c.d;
      acc += y;
    }
    out[k] = acc * 0.25;
  }
  for (const d of [225, 556]) {
    const buf = new Float32Array(d);
    let i = 0;
    for (let k = 0; k < N; k++) {
      const b = buf[i];
      const y = -out[k] + b;
      buf[i] = out[k] + b * 0.5;
      i = (i + 1) % d;
      out[k] = y;
    }
  }
  return out;
}

function sparkle(s: number, midi = 100, gain = 1) {
  place(s, 0.6, (_, t) => (Math.sin(2 * Math.PI * hz(midi) * t) + 0.5 * Math.sin(2 * Math.PI * hz(midi + 7) * t)) * env(t, 0.002, 0.12), 0.12 * gain, (noise() * 0.8), 0.8);
}

function subDrop(s: number, gain = 1) {
  place(s, 1.2, (_, t) => Math.sin(2 * Math.PI * (28 * t + 40 * 0.4 * (1 - Math.exp(-t / 0.4)))) * env(t, 0.005, 0.5), 0.6 * gain);
}

function svf(mode: "lp" | "bp" | "hp", q = 0.7) {
  let low = 0, band = 0;
  return (x: number, cutoff: number) => {
    const f = 2 * Math.sin((Math.PI * Math.min(cutoff, SR / 6)) / SR);
    low += f * band;
    const high = x - low - band / q;
    band += f * high;
    return mode === "lp" ? low : mode === "bp" ? band : high;
  };
}

function bassNote(s: number, midi: number, dur: number) {
  const lp = svf("lp", 1.1);
  place(s, dur, (_, t) => {
    const f = hz(midi);
    const v = saw(f * t) + 0.6 * Math.sin(2 * Math.PI * f * 0.5 * t);
    return lp(v, 180 + 1400 * Math.exp(-t / 0.08)) * env(t, 0.004, dur * 0.6) * duck(s + t);
  }, 0.36);
}

function clap(s: number, gain = 1) {
  const bp = svf("bp", 1.2);
  place(s, 0.3, (_, t) => {
    const bursts = [0, 0.011, 0.022].reduce((a, o) => a + (t >= o ? Math.exp(-(t - o) / 0.006) : 0), 0);
    const tail = Math.exp(-t / 0.09);
    return bp(noise() * (bursts * 0.6 + tail), 1400) * 1.6;
  }, 0.5 * gain, 0, 0.35);
}

function hat(s: number, open = false, gain = 1, pan = 0) {
  const hp = svf("hp", 0.8);
  place(s, open ? 0.25 : 0.06, (_, t) => hp(noise(), 8000) * env(t, 0.0005, open ? 0.07 : 0.018), 0.22 * gain, pan);
}

function impact(s: number, gain = 1) {
  const lp = svf("lp", 0.7);
  place(s, 2.2, (_, t) => {
    const boom = Math.sin(2 * Math.PI * (30 * t + 60 * 0.12 * (1 - Math.exp(-t / 0.12)))) * env(t, 0.002, 0.5);
    const crash = lp(noise(), 2000 + 7000 * Math.exp(-t / 0.3)) * env(t, 0.001, 0.45);
    return boom * 0.9 + crash * 0.55;
  }, 0.7 * gain, 0, 0.5);
}

function key(s: number, heavy = false) {
  const bp = svf("bp", 1.2);
  const pan = (noise() * 0.3);
  place(s, 0.05, (_, t) => (bp(noise(), heavy ? 1500 : 2400) * 1.8 + Math.sin(2 * Math.PI * 180 * t) * 0.5) * env(t, 0.0005, heavy ? 0.018 : 0.008), heavy ? 0.4 : 0.22, pan);
}

function pad(s0: number, s1: number, cutoffAt: (s: number) => number, gain: number) {
  for (let b = Math.floor(s0 / BAR); b * BAR < s1; b++) {
    const s = Math.max(s0, b * BAR);
    const e = Math.min(s1, (b + 1) * BAR);
    const { notes } = chordAt(s);
    const lpL = svf("lp", 0.9), lpR = svf("lp", 0.9);
    const detune = [-0.12, 0, 0.11];
    const len = e - s;
    const gl = gain, gr = gain;
    const start = at(s);
    for (let i = 0; i < len * SR; i++) {
      const t = i / SR;
      let vl = 0, vr = 0;
      for (const n of notes) for (const d of detune) {
        const f = hz(n + d);
        vl += saw(f * t + d);
        vr += saw(f * 1.002 * t + d * 3);
      }
      const edge = Math.min(1, t / 0.02, (len - t) / 0.02);
      const c = cutoffAt(s + t);
      const g = edge * duck(s + t) / 12;
      const k = start + i;
      if (k >= N) break;
      const l = lpL(vl, c) * g * gl, r = lpR(vr, c) * g * gr;
      L[k] += l; R[k] += r; sendL[k] += l * 0.5; sendR[k] += r * 0.5;
    }
  }
}

function pluck(s: number, midi: number, gain: number, bright: number, pan: number) {
  const lp = svf("lp", 1.4);
  place(s, 0.22, (_, t) => {
    const f = hz(midi);
    const sq = Math.sign(Math.sin(2 * Math.PI * f * t)) * 0.6 + saw(f * 2.001 * t) * 0.4;
    return lp(sq, 300 + bright * Math.exp(-t / 0.05)) * env(t, 0.002, 0.07) * duck(s + t);
  }, gain, pan, 0.4);
}

function riser(s0: number, s1: number, gain = 1) {
  const bp = svf("bp", 2.5);
  const dur = s1 - s0;
  place(s0, dur, (_, t) => {
    const p = t / dur;
    const n = bp(noise(), 400 + 9000 * p * p);
    const tone = saw(hz(48 + 24 * p) * t * (1 + p)) * 0.25;
    return (n * 1.3 + tone * p) * p * p;
  }, 0.5 * gain, 0, 0.3);
}

function rumble(s: number, dur: number, gain = 1) {
  const lp = svf("lp", 0.8);
  place(s, dur, (_, t) => lp(noise(), 90 + 200 * (t / dur)) * 3 * Math.sin(Math.PI * Math.min(1, t / dur)), 0.5 * gain);
}

function scratch(s: number) {
  const bp = svf("bp", 2);
  place(s, 0.25, (_, t) => bp(noise(), 800 + 5000 * (t / 0.25)) * env(t, 0.005, 0.1) * 2, 0.35, 0.2);
}

function thud(s: number) {
  const lp = svf("lp", 1);
  place(s, 0.3, (_, t) => {
    const f = 110 * Math.exp(-t / 0.2);
    return lp(Math.sign(Math.sin(2 * Math.PI * f * t)), 900) * env(t, 0.001, 0.08);
  }, 0.5, 0, 0.2);
}

function tick(s: number, pitch = 1, gain = 1, pan = 0) {
  const bp = svf("bp", 3);
  place(s, 0.03, (_, t) => (bp(noise(), 3200 * pitch) * 2 + Math.sin(2 * Math.PI * 2600 * pitch * t) * 0.5) * env(t, 0.0005, 0.006), 0.28 * gain, pan);
}

function whoosh(s: number, dur = 0.45, gain = 1, up = true) {
  const bp = svf("bp", 1.6);
  place(s, dur, (_, t) => {
    const p = t / dur;
    const c = up ? 300 + 5000 * p * p : 5000 - 4700 * p;
    return bp(noise(), c) * Math.sin(Math.PI * Math.min(1, p)) ** 1.5;
  }, 0.45 * gain, 0, 0.3);
}

function zap(s: number, gain = 1) {
  const lp = svf("lp", 3);
  place(s - 0.05, 0.35, (_, t) => {
    const f = 3000 * Math.exp(-t / 0.06) + 120;
    return lp(saw(f * t) + noise() * 0.3, 6000 * Math.exp(-t / 0.1) + 300) * env(t, 0.001, 0.09);
  }, 0.35 * gain, (noise() * 0.6), 0.4);
}

function kick(s: number) {
  if (!kickOn(s)) return 0;
  return Math.exp(-(((s % BEAT) + BEAT) % BEAT) / 0.11);
}

function shake(s: number) {
  let x = 0, y = 0, r = 0;
  for (const [t, a] of IMPACTS) {
    const d = s - t;
    if (d < 0 || d > 0.7) continue;
    const e = a * Math.exp(-d / 0.13);
    x += Math.sin(d * 91 + t) * 24 * e;
    y += Math.cos(d * 77 + t * 3) * 18 * e;
    r += Math.sin(d * 53 + t) * 0.7 * e;
  }
  return { x, y, r };
}

function spring(s: number, start: number, freq = 2.4, damp = 0.32) {
  const t = s - start;
  if (t <= 0) return 0;
  const w = 2 * Math.PI * freq;
  const wd = w * Math.sqrt(1 - damp * damp);
  return 1 - Math.exp(-damp * w * t) * (Math.cos(wd * t) + ((damp * w) / wd) * Math.sin(wd * t));
}

function squash(s: number, start: number, amount = 0.22): [number, number] {
  const t = s - start;
  if (t < 0) return [1, 1];
  const k = amount * Math.exp(-t / 0.09) * Math.cos(t * 38);
  return [1 + k, 1 - k];
}

function agentAt(s: number): [number, number, number] {
  const way = [{ t: START, land: 0 }, ...CUE.visits.map((v) => ({ t: v.t, land: v.land }))];
  if (s >= CUE.timelapse[0]) {
    // Time-lapse: laps around the ring, faster and faster.
    const u = s - CUE.timelapse[0];
    const laps = u * (1.2 + u * 1.6);
    const a = laps * Math.PI * 2 - Math.PI / 2;
    const r = 5.6 + Math.sin(laps * 9) * 0.6;
    return [Math.cos(a) * r, 2.2 + Math.sin(laps * 6) * 0.3, Math.sin(a) * r];
  }
  let i = 0;
  while (i < way.length - 1 && s >= way[i + 1].t) i++;
  const [ax, az] = landPos(way[i].land, s);
  const ay = landTop(way[i].land, s) + 0.8;
  if (i === way.length - 1) return [ax, ay, az];
  const next = way[i + 1];
  const u = inOutCubic(prog(s, next.t - 0.38, next.t));
  const [bx, bz] = landPos(next.land, s);
  const by = landTop(next.land, s) + 0.8;
  return [lerp(ax, bx, u), lerp(ay, by, u) + Math.sin(Math.PI * u) * 1.4 + Math.sin(s * 5) * 0.08, lerp(az, bz, u)];
}

function hexHeight(h: { land: number; rnd: number }, s: number) {
  const start = CUE.rise + h.land * 0.06 + h.rnd * 0.12;
  return 0.35 + h.rnd * 0.05 + spring(s, start, 2.2, 0.35) * (LAND_H[h.land] + h.rnd * 0.25);
}

function landGap(land: number, s: number) {
  return outBack(prog(s, groupAt(land) + 0.1, groupAt(land) + 0.4)) * 0.18 + spring(s, CUE.rise, 2, 0.5) * 0.16;
}

function hexOffset(h: Hex, s: number): [number, number] {
  const L = LANDS[h.land];
  const g = landGap(h.land, s);
  let ox = L.dir[0] * g, oz = L.dir[1] * g;
  if (h.land === RESLICE_LAND) {
    const sep = outBack(prog(s, CUE.reslice, CUE.reslice + 0.3)) * 0.4 * h.half;
    ox += -L.dir[1] * sep;
    oz += L.dir[0] * sep;
  }
  return [ox, oz];
}

function ripple(s: number, t0: number, d: number, amp: number, speed: number) {
  if (s < t0) return 0;
  const front = (s - t0) * speed;
  return amp * Math.exp(-((d - front) ** 2) / 1.4) * Math.exp(-(s - t0) / 1.3);
}

function hexLift(h: Hex, s: number) {
  let y = ripple(s, CUE.drop, h.dist, 1.4, 13) + ripple(s, CUE.slam, h.dist, 0.9, 15);
  for (const p of CUE.pulses) y += ripple(s, p, h.dist, 0.2, 11);
  const g = groupAt(h.land);
  y += Math.sin(Math.PI * prog(s, g, g + 0.4)) * 0.45;
  const k = RAIN_TARGETS.indexOf(h.i);
  if (k >= 0) {
    const t = s - CUE.rain[k];
    if (t >= 0) y -= 0.35 * Math.exp(-t / 0.12) * Math.cos(t * 28);
  }
  return y;
}

function skyTexture(n: number, flat: number, sky: SkyName) {
  if (!skyCanvas) {
    skyCanvas = document.createElement("canvas");
    skyCanvas.width = 160;
    skyCanvas.height = 90;
    skyTex = new THREE.CanvasTexture(skyCanvas);
    skyTex.colorSpace = THREE.SRGBColorSpace;
  }
  const g = skyCanvas.getContext("2d")!;
  const day = g.createLinearGradient(0, 0, 160, 90);
  const [a, b, c] = SKIES[sky].stops;
  day.addColorStop(0, a);
  day.addColorStop(0.45, b);
  day.addColorStop(1, c);
  g.globalAlpha = 1;
  g.fillStyle = day;
  g.fillRect(0, 0, 160, 90);
  if (n > 0) {
    const nt = g.createRadialGradient(80, 30, 0, 80, 30, 110);
    nt.addColorStop(0, "#1d2a6e");
    nt.addColorStop(0.7, C.night);
    g.globalAlpha = n;
    g.fillStyle = nt;
    g.fillRect(0, 0, 160, 90);
  }
  if (flat > 0) {
    g.globalAlpha = flat;
    g.fillStyle = LOCKUP_BG;
    g.fillRect(0, 0, 160, 90);
  }
  skyTex!.needsUpdate = true;
  return skyTex!;
}

function sample(s: number, field: "pos" | "look"): V3 {
  let i = 0;
  while (i < KEYS.length - 2 && s >= KEYS[i + 1].t) i++;
  const k1 = KEYS[i], k2 = KEYS[i + 1];
  if (s <= k1.t) return [...k1[field]];
  if (s >= k2.t) return [...k2[field]];
  if (k2.cut) return [...k1[field]]; // hold until the cut
  const k0 = k1.cut || i === 0 ? k1 : KEYS[i - 1];
  const k3 = i + 2 < KEYS.length && !KEYS[i + 2].cut ? KEYS[i + 2] : k2;
  const u = (s - k1.t) / (k2.t - k1.t);
  return [0, 1, 2].map((a) => cr(k0[field][a], k1[field][a], k2[field][a], k3[field][a], u)) as V3;
}

function cameraAt(s: number) {
  const pos = sample(s, "pos");
  const look = sample(s, "look");
  // Handheld drift, stronger near the ground; none once the lockup settles.
  const d = s > CUE.collapse[0] ? 0 : 0.06 + 0.12 * Math.exp(-pos[1] / 4);
  pos[0] += Math.sin(s * 1.3) * d;
  pos[1] += Math.sin(s * 1.7 + 1) * d * 0.6;
  look[0] += Math.sin(s * 0.9 + 2) * d * 0.5;
  // Whip: overshoot on arrival after the drop cut.
  if (s >= CUE.drop && s < CUE.drop + 0.6) pos[2] += Math.sin((s - CUE.drop) * 18) * 1.5 * Math.exp(-(s - CUE.drop) / 0.15);
  return { pos, look };
}

function make(key: string, w: number, h: number, draw: (g: CanvasRenderingContext2D) => void) {
  const hit = cache.get(key);
  if (hit) return hit;
  const cv = document.createElement("canvas");
  cv.width = w;
  cv.height = h;
  draw(cv.getContext("2d")!);
  const tex = new THREE.CanvasTexture(cv);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  cache.set(key, tex);
  return tex;
}

def test_extract_definitions_for_language(language: str) -> None:
    if language in _UNAVAILABLE:
        pytest.skip(f"grammar unavailable for {language}")

    spec = get_spec(language)
    assert spec is not None

    extracted = extract_file(SAMPLES[language], spec)

    names = {d.local_name for d in extracted.definitions}
    assert EXPECTED_DEFINITION_NAMES[language] <= names
    assert not extracted.parse_had_errors

def test_rust_impl_becomes_class_like_container() -> None:
    spec = get_spec("rust")
    assert spec is not None
    extracted = extract_file(SAMPLES["rust"], spec)
    kinds = {d.local_name: d.kind for d in extracted.definitions}
    assert kinds["Widget"] == "class"  # the impl block itself

def run_command_payload(command: str, shape: str = "command") -> dict:
    if shape == "command":
        payload = {"command": command}
    elif shape == "input.command":
        payload = {"input": {"command": command}}
    elif shape == "tool_input.command":
        payload = {"tool_input": {"command": command}}
    else:
        raise ValueError(shape)
    return run_hook(json.dumps(payload))

def test_alternate_command_field_shapes_are_checked() -> None:
    assert run_command_payload("rm -rf /", shape="input.command")["decision"] == "deny"
    assert run_command_payload("rm -rf /", shape="tool_input.command")["decision"] == "deny"

def test_bare_truncate_denied() -> None:
    result = run_command_payload("TRUNCATE users;")
    assert result["decision"] == "deny"

